    #region AutoRegister

    /// <summary>
    /// Instructs the S.O.S. discovery engine to automatically register the decorated class as an SOS module into its corresponding <see cref="API"/> factory.
    /// </summary>
    /// <remarks>
    /// <para>
    /// An SOS module is any class implementing one of the core <c>ISOS*</c> contracts
    /// (<see cref="ISOSTab"/>, <see cref="ISOSStatInfo"/>, <see cref="ISOSPrefab"/>, <see cref="ISOSConfig"/>, <see cref="ISOSWindowProfile"/>).
    /// </para>
    /// <para>
    /// During mod first opening (<see cref="API.Initialize"/>), the LuaCs plugin management service scans loaded assemblies
    /// for classes decorated with this attribute that implement one of the SOS module contracts:
    /// <list type="bullet">
    /// <item><description><see cref="ISOSTab"/> (or <see cref="ITab{T}"/>): Registered as an SOS module acting as a browser tab.</description></item>
    /// <item><description><see cref="ISOSStatInfo"/>: Registered as an SOS module acting as an inspector wiki section.</description></item>
    /// <item><description><see cref="ISOSPrefab"/>: Registered as an SOS module acting as a prefab data provider in the browser.</description></item>
    /// <item><description><see cref="ISOSWindowProfile"/>: Registered as an SOS module acting as a visual window layout profile.</description></item>
    /// <item><description><see cref="ISOSConfig"/>: Registered as an SOS module acting as a reactive configuration unit.</description></item>
    /// </list>
    /// </para>
    /// <para>
    /// <b>Deferred Instantiation:</b> Decorating a type with this attribute registers its factory delegate without constructing an instance immediately.
    /// Actual construction is deferred until the SOS module is first requested by the user or the active profile.
    /// </para>
    /// </remarks>
    /// <example>
    /// <code>
    /// [AutoRegister("MyMod.RadiationSection", order: 5.0, active: true)]
    /// public class RadiationSection : ISOSStatInfo
    /// {
    ///     // ...
    /// }
    /// </code>
    /// </example>
    [AttributeUsage(AttributeTargets.Class)]
    public class AutoRegisterAttribute : Attribute
    {
        /// <summary>
        /// Gets the unique string identifier used as the dictionary key in the internal registries.
        /// If <c>null</c>, the SDK automatically defaults to <c>Type.FullName ?? Type.Name</c>.
        /// </summary>
        public readonly string? Id;

        /// <summary>
        /// Gets the numerical sorting order that determines the SOS module's execution or layout sequence relative to others.
        /// Lower values appear earlier or execute first. Defaults to <c>0.0</c>.
        /// </summary>
        public readonly double Order;

        /// <summary>
        /// Gets a value indicating whether the SOS module is enabled upon initial discovery.
        /// If <c>false</c>, the SOS module is registered but ignored during queries until explicitly activated via <see cref="API"/>.
        /// Defaults to <c>true</c>.
        /// </summary>
        public readonly bool Active;

        /// <summary>
        /// Initializes a new instance of the <see cref="AutoRegisterAttribute"/> class with specified registration metadata.
        /// </summary>
        /// <param name="id">Optional unique identifier. If <c>null</c> or whitespace, defaults to the declaring class's full name.</param>
        /// <param name="order">Priority order determining placement in UI lists or execution chains. Lower values appear first. Defaults to <c>0.0</c>.</param>
        /// <param name="active">Whether the SOS module is initially enabled. Defaults to <c>true</c>.</param>
        public AutoRegisterAttribute(string? id = null, double order = 0.0, bool active = true)
        {
            Id = id;
            Order = order;
            Active = active;
        }
    }

    #endregion

    #region Interfaces

    /// <summary>
    /// Exposes an identifier property used to uniquely distinguish an object.
    /// </summary>
    [EditorBrowsable(EditorBrowsableState.Never)]
    public interface IIdentifier
    {
        /// <summary>
        /// Gets the unique string identifier of this instance.
        /// By default, returns the full name of the implementing runtime type.
        /// </summary>
        string Id => GetType().FullOrName();
    }

    /// <summary>
    /// Defines an SOS module acting as a modular, generic UI tab capable of inspecting and interacting with entities of type <typeparamref name="T"/>.
    /// </summary>
    /// <typeparam name="T">The data entity type inspected by this tab (e.g., <see cref="Barotrauma.Prefab"/> or <see cref="Barotrauma.Character"/>).</typeparam>
    /// <remarks>
    /// <para>
    /// <b>Lifecycle Flow:</b>
    /// <list type="number">
    /// <item><description><see cref="Init"/>: Invoked once per widget construction with the owned content frame and tab bar button. Deferred constructor: store the frame and build the static skeleton; the widget triggers <see cref="Update"/> right after when a valid target exists.</description></item>
    /// <item><description><see cref="CanHandle"/>: Evaluated whenever a new target entity is selected to determine if this tab applies.</description></item>
    /// <item><description><see cref="Update"/>: Invoked on the active tab whenever it is selected or its target changes. Rebuild content on the stored frame.</description></item>
    /// <item><description><see cref="IDisposable.Dispose"/>: (If implemented) Invoked when the parent window profile or widget is closed to release Monogame textures or frames.</description></item>
    /// </list>
    /// </para>
    /// <para>
    /// Visibility of both the content frame and the button is owned exclusively by the hosting tab widget (<see cref="GUI.GUITab{T}"/>).
    /// </para>
    /// </remarks>
    /// <example>
    /// <code>
    /// [AutoRegister("MyMod.SubmarineTab", order: 10.0)]
    /// public class SubmarineTab : ITab&lt;SubmarineInfo&gt;
    /// {
    ///     private GUIFrame? _container;
    ///     public bool CanHandle(SubmarineInfo sub) => sub != null;
    ///     public void Init(GUIFrame container, GUIButton tabButton)
    ///     {
    ///         _container = container;
    ///         /* Build static skeleton on container */
    ///     }
    ///     public void Update(Prefab target) { /* Draw sub stats */ }
    ///     public GUIButton CreateTabButton(RectTransform tabRectT, string _) =>
    ///         TabDefaults.CreateTabButton(tabRectT, "DETAILS", "Submarine details.");
    /// }
    /// </code>
    /// </example>
    [EditorBrowsable(EditorBrowsableState.Never), DefaultClass<TabDefaults>]
    public interface ITab<T> : IIdentifier
    {
        /// <summary>
        /// Evaluates whether this tab is capable of displaying meaningful information for the given <paramref name="item"/>.
        /// </summary>
        /// <param name="item">The target entity currently selected.</param>
        /// <returns><c>true</c> if this tab should appear in the tab bar for this entity; otherwise, <c>false</c>.</returns>
        bool CanHandle(T item) => true;

        /// <summary>
        /// Initializes the tab when the widget is constructed. Deferred constructor: store the owned frame and build the static skeleton.
        /// </summary>
        /// <param name="container">The content frame owned by the widget. Store it and build the visual hierarchy on its <see cref="Barotrauma.RectTransform"/>; never toggle its <c>Visible</c>.</param>
        /// <param name="tabButton">The tab bar button created via <see cref="CreateTabButton"/>. Optionally retouch it here (text, style); never toggle <c>Visible</c>/<c>Selected</c> nor wire <c>OnClicked</c>: the widget owns those.</param>
        void Init(GUIFrame container, GUIButton tabButton);

        /// <summary>
        /// Rebuilds the tab's content for the newly selected <paramref name="target"/>.
        /// Invoked on the active tab only, and only when the target instance changed.
        /// </summary>
        /// <param name="target">The entity to inspect and visualize.</param>
        void Update(T target) { }

        /// <summary>
        /// Creates the tab bar button, resolving its title and tooltip from localization
        /// (<c>{id}.title</c> / <c>{id}.tooltip</c>) with a humanized <paramref name="id"/> fallback.
        /// Override to customize text, tooltip or style; the widget assigns selection, click and visibility afterwards.
        /// </summary>
        /// <param name="rectT">The tab bar area where the button will live.</param>
        /// <param name="id">The unique identifier of the tab, used for the localization lookup.</param>
        /// <returns>A configured <see cref="Barotrauma.GUIButton"/> without click wiring.</returns>
        GUIButton CreateTabButton(RectTransform rectT, string id)
            => TabDefaults.CreateTabButton(rectT, id);
    }

    /// <summary>
    /// Defines an SOS module acting as a modular prefab inspection tab (type alias for <see cref="ITab{T}"/> where <c>T</c> is <see cref="Barotrauma.Prefab"/>).
    /// </summary>
    public interface ISOSTab : ITab<Prefab> { }

    /// <summary>
    /// Defines an SOS module acting as a modular, completely stateless wiki inspector section rendered in the right-hand panel of S.O.S.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Instances are cached as reusable services in the SDK registry.
    /// All parsing, filtering, and visual row construction must occur locally within <see cref="Draw"/>.
    /// </para>
    /// <para>
    /// <b>Rendering Pipeline:</b> When the player selects a prefab, the active window profile iterates all active sections:
    /// <list type="bullet">
    /// <item><description>If the prefab contains relevant data (e.g., medical treatments, weapon stats, container capacities), the section renders rows into <c>rectT</c> using <see cref="GUI.GUILayoutBuilder"/>.</description></item>
    /// <item><description>If the prefab is not applicable, the section draws nothing: no empty frames or layout dividers.</description></item>
    /// </list>
    /// </para>
    /// </remarks>
    /// <example>
    /// <code>
    /// [AutoRegister(order: 2.0)]
    /// public class RadiationStatInfo : ISOSStatInfo
    /// {
    ///     public void Draw(RectTransform rectT, Prefab prefab)
    ///     {
    ///         if (prefab is not ItemPrefab item || !item.Tags.Contains("radioactive"))
    ///             return;
    ///
    ///         using var l = new GUILayoutBuilder(rectT);
    ///         l.Header("RADIATION HAZARD", Color.GreenYellow);
    ///         l.Row("Radiation Output:", "High", Color.Red);
    ///     }
    /// }
    /// </code>
    /// </example>
    public interface ISOSStatInfo
    {
        /// <summary>
        /// Analyzes the specified <paramref name="prefab"/> and appends visual layout rows into <paramref name="rectT"/> if applicable.
        /// </summary>
        /// <param name="rectT">Dedicated layout space provided by the host for this section. Build a <see cref="GUI.GUILayoutBuilder"/> on it; draw nothing when not applicable.</param>
        /// <param name="prefab">The target entity currently being inspected.</param>
        void Draw(RectTransform rectT, Prefab prefab);
    }

    /// <summary>
    /// Defines an SOS module acting as an extensible configuration unit with lifecycle persistence, factory defaults, and declarative UI rendering.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Implementations are managed through <see cref="API"/> and integrate with <see cref="Configs.ConfigDirtySaver"/>
    /// to buffer changes and persist them safely using Barotrauma's LuaCs config service.
    /// </para>
    /// <para>
    /// <b>Lifecycle Methods:</b>
    /// <list type="bullet">
    /// <item><term><see cref="Load"/>:</term><description>Invoked during client startup (<see cref="Configs.ConfigHelper.LoadConfigs"/>) to load saved values into memory.</description></item>
    /// <item><term><see cref="Save"/>:</term><description>Invoked on window dismissal or round transitions to serialize modified values to disk.</description></item>
    /// <item><term><see cref="Reset"/>:</term><description>Restores all settings managed by this unit to their default values.</description></item>
    /// <item><term><see cref="Draw"/>:</term><description>Constructs the interactive configuration UI in the settings window using <see cref="GUI.GUILayoutBuilder"/>.</description></item>
    /// </list>
    /// </para>
    /// </remarks>
    /// <example>
    /// <code>
    /// [AutoRegister("MyMod.Settings", order: 5.0)]
    /// public class MyModSettings : ConfigDirtySaver, ISOSConfig
    /// {
    ///     public void Load() { /* ... */ }
    ///     public void Save() { /* ... */ }
    ///     public void Reset() { /* ... */ }
    ///     public void Draw(RectTransform rectT)
    ///     {
    ///         using var l = new GUILayoutBuilder(container);
    ///         l.Header("MY MOD CONFIG", Color.Gold);
    ///         l.ButtonToResetSection(this);
    ///         return;
    ///     }
    /// }
    /// </code>
    /// </example>
    [DefaultClass<ConfigDefaults>]
    public interface ISOSConfig
    {
        /// <summary>
        /// Loads saved settings from persistent storage into runtime memory.
        /// </summary>
        void Load();

        /// <summary>
        /// Persists modified configuration properties to disk.
        /// </summary>
        void Save();

        /// <summary>
        /// Reverts all settings managed by this configuration back to their factory default values.
        /// </summary>
        void Reset() { }

        /// <summary>
        /// Constructs the interactive configuration UI in the settings window.
        /// </summary>
        /// <param name="rectT">Dedicated layout space provided by the host. Build a <see cref="GUI.GUILayoutBuilder"/> on it.</param>
        void Draw(RectTransform rectT) { }
    }

    /// <summary>
    /// Represents parsed search criteria used by <see cref="ISOSPrefab.GetPrefabs(IPrefabFilter)"/> to filter entities in the browser.
    /// </summary>
    /// <remarks>
    /// Supports advanced search prefixes parsed by <c>PrefabFilterHelper.SearchFilter</c>:
    /// <list type="bullet">
    /// <item><term>@</term><description>Filters by Content Package / Mod Name (<see cref="Mod"/>).</description></item>
    /// <item><term>#</term><description>Filters by Category enum string (<see cref="Category"/>).</description></item>
    /// <item><term>$</term><description>Filters by item or affliction tag (<see cref="Tag"/>).</description></item>
    /// <item><term>&amp;</term><description>Filters by equipment slot string (<see cref="Slot"/>).</description></item>
    /// <item><term>!</term><description>Filters by exact or partial identifier string (<see cref="ID"/>).</description></item>
    /// <item><term>%</term><description>Filters by Prefab type name (<see cref="PrefabType"/>).</description></item>
    /// </list>
    /// </remarks>
    public interface IPrefabFilter
    {
        /// <summary>
        /// Gets general search keywords that match across names, identifiers, or content package titles.
        /// </summary>
        List<string> General { get; }

        /// <summary>
        /// Gets content package / mod name filter tokens (prefixed with '@').
        /// </summary>
        List<string> Mod { get; }

        /// <summary>
        /// Gets entity category filter tokens (prefixed with '#').
        /// </summary>
        List<string> Category { get; }

        /// <summary>
        /// Gets tag filter tokens (prefixed with '$').
        /// </summary>
        List<string> Tag { get; }

        /// <summary>
        /// Gets equipment inventory slot filter tokens (prefixed with '&amp;').
        /// </summary>
        List<string> Slot { get; }

        /// <summary>
        /// Gets exact identifier filter tokens (prefixed with '!').
        /// </summary>
        List<string> ID { get; }

        /// <summary>
        /// Gets entity prefab type filter tokens (prefixed with '%').
        /// </summary>
        List<string> PrefabType { get; }
    }

    /// <summary>
    /// Defines an SOS module acting as an extensible prefab data source that feeds entities into the S.O.S. left sidebar browser.
    /// </summary>
    /// <remarks>
    /// By implementing this interface and decorating the class with <see cref="AutoRegisterAttribute"/>,
    /// third-party mods can introduce new browsable entity types (such as custom subassemblies, event prefabs, or jobs)
    /// into the main S.O.S. interface.
    /// </remarks>
    /// <example>
    /// <code>
    /// [AutoRegister("MyMod.JobProvider", order: 3.0)]
    /// public class JobPrefabProvider : ISOSPrefab
    /// {
    ///     public IEnumerable&lt;Prefab&gt; GetPrefabs(IPrefabFilter filter)
    ///     {
    ///         return JobPrefab.Prefabs.Where(j => filter.General.Count == 0 || j.Name.Value.Contains(filter.General[0]));
    ///     }
    /// }
    /// </code>
    /// </example>
    public interface ISOSPrefab
    {
        /// <summary>
        /// Queries and yields all prefabs provided by this source that satisfy the specified <paramref name="filter"/>.
        /// A provider serves its own prefabs whatever their runtime types are; related subtypes stay grouped by the browser.
        /// </summary>
        /// <param name="filter">The structured search filter containing text, category, tag, and mod tokens.</param>
        /// <returns>An enumerable sequence of matching <see cref="Barotrauma.Prefab"/> instances.</returns>
        IEnumerable<Prefab> GetPrefabs(IPrefabFilter filter);

        /// <summary>
        /// Constructs right-click contextual action options for an entity belonging to this provider.
        /// </summary>
        /// <param name="prefab">The prefab being right-clicked.</param>
        /// <returns>Provider-specific context menu options (e.g., "Track to HUD"). The hosting browser appends the baseline actions once.</returns>
        [DefaultClass<PrefabDefaults>]
        List<ContextMenuOption> GetContextOptions(Prefab prefab) => [];
    }

    /// <summary>
    /// Defines an SOS module acting as an interchangeable visual presentation layout for the S.O.S. window.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Implementations inherit from <see cref="GUI.GUIWindow"/> and define how the screen space is partitioned
    /// (e.g., 3-column browser view, compact single-column inspector, or floating HUD tool).
    /// </para>
    /// <para>
    /// <b>Hot-Swapping:</b> Profiles can be changed dynamically at runtime via <see cref="API.Emit{T}(string, T, double?, bool)"/>
    /// using <see cref="CommKeys.ChangeProfile"/>. When switching profiles, the outgoing profile is disposed and the incoming profile
    /// is instantiated, initialized via <see cref="Init"/>, and opened seamlessly.
    /// </para>
    /// </remarks>
    /// <example>
    /// <code>
    /// [AutoRegister("MyMod.CompactProfile", order: 20.0)]
    /// public class CompactProfile : GUIWindow, ISOSWindowProfile
    /// {
    ///     public string DisplayName => "Compact Inspector";
    ///     public string Description => "Minimalist floating window.";
    ///     public void Init() { /* Build UI */ }
    ///     public void Update() { /* Frame update */ }
    /// }
    /// </code>
    /// </example>
    [DefaultClass<WindowProfileDefaults>]
    public interface ISOSWindowProfile : IIdentifier, IDisposable
    {

        /// <summary>
        /// Gets optional profile-specific configuration settings (e.g., custom panel widths, saved layout presets).
        /// Returns <c>null</c> if the profile does not require persistent settings.
        /// </summary>
        ISOSConfig? ProfileConfig => null;

        /// <summary>
        /// Initializes the profile's visual hierarchy, event subscriptions, and geometry state.
        /// Invoked immediately after construction when the profile becomes active.
        /// </summary>
        void Init();

        /// <summary>
        /// Performs frame-by-frame updates, layout checks, input handling, and debouncing while the window is visible.
        /// </summary>
        void Update();
    }

    #endregion

    #region Default Proxy Classes

    /// <summary>
    /// Provides default fallback implementations for tab SOS modules when adapted via <see cref="DuckProxy{T}"/>.
    /// </summary>
    [EditorBrowsable(EditorBrowsableState.Never)]
    internal sealed class TabDefaults
    {
        private TabDefaults() { }

        /// <summary>
        /// Evaluates whether this tab is capable of displaying meaningful information for the given <c>item</c>.
        /// </summary>
        /// <param name="_"><c>item</c> - The target entity currently selected.</param>
        /// <returns><c>true</c> if this tab should appear in the tab bar for this entity; otherwise, <c>false</c>.</returns>
        public static bool CanHandle(Prefab _) => true;

        /// <summary>
        /// Rebuilds the tab's content for the newly selected <c>target</c>.
        /// Invoked on the active tab only, and only when the target instance changed.
        /// </summary>
        /// <param name="_"><c>target</c> - The entity to inspect and visualize.</param>
        public static void Update(Prefab _) { }

        /// <summary>
        /// Creates the default tab button for the given tab identifier, resolving its title and tooltip
        /// from localization (<c>{id}.title</c> / <c>{id}.tooltip</c>).
        /// </summary>
        /// <param name="parent">The parent rectangle transform (usually the tab bar content).</param>
        /// <param name="id">The unique identifier of the tab, used for the localization lookup.</param>
        /// <returns>A configured <see cref="Barotrauma.GUIButton"/> without click wiring; the hosting tab widget assigns it.</returns>
        public static GUIButton CreateTabButton(RectTransform parent, string id)
        {
            var title = Texts.Get($"{id}.title", id.Split('.')[^1].FormatCamelCaseWithSpaces());
            var tooltip = Texts.Get($"{id}.tooltip");
            return CreateTabButton(parent, title, tooltip);
        }

        /// <summary>
        /// Creates a standard tab button styled with the "MainMenuNotificationButton" template, sized to fit <paramref name="text"/>.
        /// </summary>
        /// <param name="parent">The parent rectangle transform (usually the tab bar content).</param>
        /// <param name="text">The label displayed on the button.</param>
        /// <param name="tooltip">Optional tooltip text. If <c>null</c> or empty, no tooltip is set.</param>
        /// <returns>A configured <see cref="Barotrauma.GUIButton"/> without click wiring; the hosting tab widget assigns it.</returns>
        public static GUIButton CreateTabButton(RectTransform parent, RichString text, RichString? tooltip = null)
        {
            Vector2 textSize = GUIStyle.SmallFont.MeasureString(text);
            int width = (int)textSize.X + 24;
            var tabBtn = new GUIButton(new(new Point(width, 32), parent) { IsFixedSize = true }, text, style: "MainMenuNotificationButton");
            if (!tooltip.IsNullOrEmpty()) tabBtn.ToolTip = tooltip;
            return tabBtn;
        }
    }

